mapper.select:
SELECT device_id FROM device
AND fcm_token = #{fcmToken}
ORDER BY device_id DESC LIMIT 1

mapper.update:
UPDATE device_permission
location_status = #{locationStatus}, camera_status = #{cameraStatus}, notification_status = #{notificationStatus}, updated_at = NOW()
WHERE device_id = #{deviceId}

mapper.select:
SELECT n.notification_id, n.type, n.title, n.body, n.target_type, n.target_id,
CASE WHEN n.read_yn = 'Y' THEN 1 ELSE 0 END AS `read`, n.created_at FROM notification n
AND n.member_id = #{memberId}
AND n.notification_id < #{cursor}
ORDER BY n.notification_id DESC LIMIT #{size}

SELECT member_id FROM member_rel_trip
AND trip_id = #{tripId} AND status = 'JOINED' AND member_id <> #{exceptMemberId}
ORDER BY member_id
